36	import org.springframework.samples.petclinic.mapper.PetMapper;
37	import org.springframework.samples.petclinic.mapper.VisitMapper;
38	import org.springframework.samples.petclinic.model.Owner;
39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
42	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
44	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
45	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
46	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
47	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
48	import org.springframework.samples.petclinic.rest.advice.RequiredFieldsMissingException;
49	import org.springframework.samples.petclinic.rest.api.OwnersApi;
50	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
51	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
52	import org.springframework.samples.petclinic.rest.dto.PetDto;
53	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
54	import org.springframework.samples.petclinic.rest.dto.VisitDto;
55	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
56	import org.springframework.samples.petclinic.service.ClinicService;
57	import org.springframework.security.access.prepost.PreAuthorize;
58	import org.springframework.web.bind.annotation.CrossOrigin;
59	import org.springframework.web.bind.annotation.RequestMapping;
60	import org.springframework.web.bind.annotation.RestController;
61	import org.springframework.web.util.UriComponentsBuilder;
62	
63	import jakarta.transaction.Transactional;
64	
65	/**
66	 * @author Vitaliy Fedoriv
67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /**
75	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
76	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
77	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
78	     */
79	    private static final Pattern EMAIL_PATTERN =
80	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
81	
82	    /**
83	     * Dedicated audit logger. On a successful create an audit line carrying the owner id, the
84	     * customerCode, the registrationDate and the membershipLevel is emitted through this logger.
85	     */
86	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
87	
88	    private final ClinicService clinicService;
89	
90	    private final OwnerMapper ownerMapper;
91	
92	    private final PetMapper petMapper;
93	
94	    private final VisitMapper visitMapper;
95	
96	    public OwnerRestControllerV1(ClinicService clinicService,
97	                                 OwnerMapper ownerMapper,
98	                                 PetMapper petMapper,
99	                                 VisitMapper visitMapper) {
100	        this.clinicService = clinicService;
101	        this.ownerMapper = ownerMapper;
102	        this.petMapper = petMapper;
103	        this.visitMapper = visitMapper;
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
109	        Collection<Owner> owners;
110	        if (lastName != null) {
111	            owners = this.clinicService.findOwnerByLastName(lastName);
112	        } else {
113	            owners = this.clinicService.findAllOwners();
114	        }
115	        if (owners.isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
119	    }
120	
121	    /**
122	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
123	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
124	     */
125	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
126	        List<String> missing = new ArrayList<>();
127	        if (isBlank(ownerFieldsDto.getFirstName())) {
128	            missing.add("firstName");
129	        }
130	        if (isBlank(ownerFieldsDto.getLastName())) {
131	            missing.add("lastName");
132	        }
133	        if (isBlank(ownerFieldsDto.getAddress())) {
134	            missing.add("address");
135	        }
136	        if (isBlank(ownerFieldsDto.getCity())) {
137	            missing.add("city");
138	        }
139	        if (isBlank(ownerFieldsDto.getTelephone())) {
140	            missing.add("telephone");
141	        }
142	        if (!missing.isEmpty()) {
143	            throw new RequiredFieldsMissingException(missing);
144	        }
145	    }
146	
147	    private static boolean isBlank(String value) {
148	        return value == null || value.isBlank();
149	    }
150	
151	    /**
152	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
153	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
154	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
155	     * normalized value is what gets stored, returned and used for every address comparison; a value
156	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
157	     * rejects it.
158	     *
159	     * @param address the raw address as supplied by the caller, may be {@code null}
160	     * @return the normalized address ({@code ""} when blank or {@code null})
161	     */
162	    private static String normalizeAddress(String address) {
163	        if (address == null) {
164	            return "";
165	        }
166	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
167	        if (collapsed.isEmpty()) {
168	            return "";
169	        }
170	        String[] tokens = collapsed.split(" ");
171	        StringBuilder sb = new StringBuilder(collapsed.length());
172	        for (int i = 0; i < tokens.length; i++) {
173	            String token = tokens[i];
174	            switch (token) {
175	                case "ST" -> token = "STREET";
176	                case "RD" -> token = "ROAD";
177	                case "AVE" -> token = "AVENUE";
178	                default -> { }
179	            }
180	            if (i > 0) {
181	                sb.append(' ');
182	            }
183	            sb.append(token);
184	        }
185	        return sb.toString();
186	    }
187	
188	    /**
189	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
190	     * A leading {@code +} and its country code are kept as given; otherwise the country code
191	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
192	     * The result must carry 8 to 15 digits after the {@code +}. In addition, when the country code
193	     * is recognized the national number must have the exact length that code requires ({@code +61}
194	     * expects 9 national digits, {@code +1} expects 10). Returns the E.164 string to be stored and
195	     * returned.
196	     *
197	     * @param telephone the raw telephone as supplied by the caller
198	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
199	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
200	     *     national-number length is wrong for its country code
201	     */
202	    private static String normalizeTelephone(String telephone) {
203	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
204	        String e164;
205	        if (cleaned.startsWith("+")) {
206	            e164 = "+" + cleaned.substring(1);
207	        } else {
208	            String national = cleaned;
209	            if (national.startsWith("0")) {
210	                national = national.substring(1);
211	            }
212	            e164 = "+61" + national;
213	        }
214	        String digits = e164.substring(1);
215	        if (!digits.matches("\\d{8,15}")) {
216	            throw new InvalidTelephoneException(
217	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
218	        }
219	        if (digits.startsWith("61")) {
220	            requireNationalLength(digits.substring(2), 9, "+61");
221	        } else if (digits.startsWith("1")) {
222	            requireNationalLength(digits.substring(1), 10, "+1");
223	        }
224	        return e164;
225	    }
226	
227	    /**
228	     * Enforces that the national portion of an E.164 number has the exact number of digits its
229	     * country code requires.
230	     *
231	     * @param national the national-number digits (the part after the country code)
232	     * @param expected the exact national-number length the country code requires
233	     * @param countryCode the country code, for the error message
234	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
235	     */
236	    private static void requireNationalLength(String national, int expected, String countryCode) {
237	        if (national.length() != expected) {
238	            throw new InvalidTelephoneException(
239	                "Telephone with country code '" + countryCode + "' must have " + expected
240	                    + " national digits");
241	        }
242	    }
243	
244	    /**
245	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
246	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
247	     *
248	     * @param email the raw email as supplied by the caller, may be {@code null}
249	     * @return the lower-cased email, or {@code null} when none was supplied
250	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
251	     */
252	    private static String normalizeEmail(String email) {
253	        if (email == null || email.isBlank()) {
254	            return null;
255	        }
256	        String trimmed = email.trim();
257	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
258	            throw new InvalidEmailException("Email must be a syntactically valid address");
259	        }
260	        return trimmed.toLowerCase(Locale.ROOT);
261	    }
262	
263	    /**
264	     * Derives the single duplicate-detection key that consolidates the former separate telephone,
265	     * email and household checks. The key is {@code normalizedTelephone + '|' + email + '|' +
266	     * householdId}, where the email segment is the empty string when the owner has no email. Because
267	     * the telephone is part of the key, two owners that differ in any one segment (for example two
268	     * members of the same household with different telephones) produce different keys.
269	     *
270	     * @param normalizedTelephone the E.164 telephone of the owner
271	     * @param email the lower-cased email of the owner, may be {@code null}
272	     * @param householdId the stable household identifier of the owner, may be {@code null}
273	     * @return the derived identity key
274	     */
275	    private static String deriveIdentityKey(String normalizedTelephone, String email, String householdId) {
276	        return (normalizedTelephone == null ? "" : normalizedTelephone)
277	            + "|" + (email == null ? "" : email)
278	            + "|" + (householdId == null ? "" : householdId);
279	    }
280	
281	    /**
282	     * Rejects a create only when the new owner's whole {@code identityKey} equals that of an existing
283	     * owner. This one check replaces the former separate telephone, email and household duplicate
284	     * checks: only an exact full-key match is a duplicate, so two owners that differ in any single
285	     * segment are both allowed. Each existing owner's key is derived from its stored, already
286	     * normalized telephone, email and household identifier.
287	     *
288	     * @param identityKey the derived identity key of the owner being created
289	     * @throws DuplicateIdentityException if another owner already has this identity key
290	     */
291	    private void rejectDuplicateIdentity(String identityKey) {
292	        boolean inUse = this.clinicService.findAllOwners().stream()
293	            .anyMatch(existing -> identityKey.equals(
294	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
295	        if (inUse) {
296	            throw new DuplicateIdentityException(
297	                "An owner with the same identity key already exists");
298	        }
299	    }
300	
301	    /**
302	     * Finds a soft-match "possible duplicate" for the owner being created: an existing owner that is
303	     * not a hard identity duplicate but shares this owner's last name (compared case-insensitively) and
304	     * postcode while carrying a different telephone. When the postcode is absent no owner can share it,
305	     * so there is never a match. When several existing owners qualify the one with the lowest id is
306	     * returned, so the result is deterministic.
307	     *
308	     * @param lastName the last name of the owner being created
309	     * @param postcode the postcode of the owner being created, may be {@code null}
310	     * @param normalizedTelephone the E.164 telephone of the owner being created
311	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
312	     */
313	    private Integer findPossibleDuplicateOf(String lastName, String postcode, String normalizedTelephone) {
314	        if (postcode == null || postcode.isBlank()) {
315	            return null;
316	        }
317	        String normalizedLastName = normalizeName(lastName);
318	        return this.clinicService.findAllOwners().stream()
319	            .filter(existing -> normalizedLastName.equals(normalizeName(existing.getLastName())))
320	            .filter(existing -> postcode.equals(existing.getPostcode()))
321	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
322	            .map(Owner::getId)
323	            .filter(java.util.Objects::nonNull)
324	            .min(Integer::compareTo)
325	            .orElse(null);
326	    }
327	
328	    /**
329	     * Normalizes a value for household comparison by trimming, collapsing every run of whitespace to
330	     * a single space and lower-casing, so the comparison is case-insensitive with collapsed whitespace.
331	     *
332	     * @param value the raw value, may be {@code null}
333	     * @return the normalized value ({@code ""} when {@code value} is {@code null})
334	     */
335	    private static String normalizeForHousehold(String value) {
336	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
337	    }
338	
339	    /**
340	     * Derives the stable household identifier for an owner from the normalized last name and address.
341	     * The value is a deterministic function of those two fields (compared case-insensitively with
342	     * collapsed whitespace), so every owner in the same
343	     * household — including owners who knowingly join it via {@code sharesHousehold} — is assigned the
344	     * same identifier without any existing record having to be updated. Formatted {@code 'HH-<HEX12>'}
345	     * where {@code HEX12} is the upper-cased first twelve hex characters of the SHA-256 of the two
346	     * normalized fields.
347	     *
348	     * @param lastName the last name of the owner being created
349	     * @param address the address of the owner being created
350	     * @return the stable household identifier
351	     */
352	    private static String householdId(String lastName, String address) {
353	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
354	        try {
355	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
356	            StringBuilder sb = new StringBuilder(digest.length * 2);
357	            for (byte b : digest) {
358	                sb.append(String.format("%02x", b));
359	            }
360	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
361	        } catch (NoSuchAlgorithmException e) {
362	            throw new IllegalStateException("SHA-256 not available", e);
363	        }
364	    }
365	
366	    /**
367	     * The maximum number of owners a single city may contain. A create whose city already holds this
368	     * many owners is rejected, so a city never grows beyond this capacity.
369	     */
370	    private static final int CITY_CAPACITY = 50;
371	
372	    /**
373	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
374	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
375	     * trimmed. The count reflects the
376	     * state before the new owner is persisted, so it excludes the owner being created.
377	     *
378	     * @param city the city of the owner being created
379	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
380	     */
381	    private void rejectCityAtCapacity(String city) {
382	        String normalizedCity = normalizeName(city);
383	        long ownersInCity = this.clinicService.findAllOwners().stream()
384	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
385	            .count();
386	        if (ownersInCity >= CITY_CAPACITY) {
387	            throw new CityAtCapacityException(
388	                "The city already contains the maximum number of owners");
389	        }
390	    }
391	
392	    /**
393	     * The maximum number of owners that may be created on a single day. A create made once this many
394	     * owners already carry today's {@code registrationDate} is rejected, so no more than this many
395	     * owners are registered per day.
396	     */
397	    private static final int DAILY_OWNER_LIMIT = 100;
398	
399	    /**
400	     * Rejects a create once {@link #DAILY_OWNER_LIMIT} or more owners have already been created for
401	     * the given business day, counted by {@code registrationDate} equal to the effective (weekend
402	     * rolled forward) registration date of the owner being created. The count reflects the state
403	     * before the new owner is persisted, so it excludes the owner being created.
404	     *
405	     * @param registrationDate the effective business-day registration date of the owner being created
406	     * @throws DailyOwnerLimitExceededException if the day already holds {@link #DAILY_OWNER_LIMIT} owners
407	     */
408	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
409	        long ownersToday = this.clinicService.findAllOwners().stream()
410	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
411	            .count();
412	        if (ownersToday >= DAILY_OWNER_LIMIT) {
413	            throw new DailyOwnerLimitExceededException(
414	                "The maximum number of owners for today has already been reached");
415	        }
416	    }
417	
418	    /**
419	     * The number of owners that may already exist for a business day before a create is flagged with
420	     * a bulk-signup warning. Once more than this many owners already carry the effective registration
421	     * date, the created owner's {@code bulkSignupWarning} is set to {@code true}.
422	     */
423	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
424	
425	    /**
426	     * Determines whether a create should be flagged with a bulk-signup warning, i.e. whether more than
427	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for the given business day,
428	     * counted by {@code registrationDate} equal to the effective (weekend rolled forward) registration
429	     * date of the owner being created. The count reflects the state before the new owner is persisted,
430	     * so it excludes the owner being created.
431	     *
432	     * @param registrationDate the effective business-day registration date of the owner being created
433	     * @return {@code true} when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the date
434	     */
435	    private boolean bulkSignupWarning(LocalDate registrationDate) {
436	        long ownersToday = this.clinicService.findAllOwners().stream()
437	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
438	            .count();
439	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
440	    }
441	
442	    /**
443	     * Rolls a registration date forward to a business day: a Saturday or Sunday is advanced to the
444	     * following Monday, any weekday is returned unchanged.
445	     *
446	     * @param date the effective registration date, supplied or defaulted to the server date
447	     * @return the same date when it is a weekday, otherwise the next Monday
448	     */
449	    private static LocalDate toBusinessDay(LocalDate date) {
450	        DayOfWeek dayOfWeek = date.getDayOfWeek();
451	        if (dayOfWeek == DayOfWeek.SATURDAY) {
452	            return date.plusDays(2);
453	        }
454	        if (dayOfWeek == DayOfWeek.SUNDAY) {
455	            return date.plusDays(1);
456	        }
457	        return date;
458	    }
459	
460	    /**
461	     * Builds the customer code assigned to an owner on create, formatted {@code '<REGION>-<HASH8>'}
462	     * where {@code REGION} is the region code derived from the owner's postcode (the region whose
463	     * inclusive range contains the postcode, or {@code 'UNKNOWN'} when the postcode is absent or in
464	     * no known range) and {@code HASH8} is the first eight upper-cased hex characters of the SHA-256
465	     * of {@code normalizedTelephone + lastName}, e.g. {@code 'NSW-1A2B3C4D'}. There is no sequence
466	     * component: the identity is a pure region-and-hash value.
467	     *
468	     * @param postcode the postcode of the owner being created, may be {@code null}
469	     * @param normalizedTelephone the E.164 telephone of the owner being created
470	     * @param lastName the last name of the owner being created
471	     * @return the formatted customer code
472	     */
473	    private String customerCode(String postcode, String normalizedTelephone, String lastName) {
474	        return regionFromPostcode(postcode) + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
475	    }
476	
477	    /**
478	     * Returns the region code whose inclusive postcode range contains the given 4-digit postcode
479	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code 'UNKNOWN'} when the postcode is
480	     * {@code null}, non-numeric, or in no known range.
481	     *
482	     * @param postcode the postcode, may be {@code null}
483	     * @return the region code, or {@code 'UNKNOWN'}
484	     */
485	    private static String regionFromPostcode(String postcode) {
486	        if (postcode == null || postcode.isBlank()) {
487	            return "UNKNOWN";
488	        }
489	        int code;
490	        try {
491	            code = Integer.parseInt(postcode.trim());
492	        } catch (NumberFormatException e) {
493	            return "UNKNOWN";
494	        }
495	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
496	            int[] range = entry.getValue();
497	            if (code >= range[0] && code <= range[1]) {
498	                return entry.getKey();
499	            }
500	        }
501	        return "UNKNOWN";
502	    }
503	
504	    /**
505	     * Computes the SHA-256 of {@code value} and returns its first {@code length} hex characters,
506	     * upper-cased.
507	     *
508	     * @param value the string to hash
509	     * @param length the number of leading hex characters to return
510	     * @return the upper-cased hex prefix of the digest
511	     */
512	    private static String sha256HexPrefix(String value, int length) {
513	        try {
514	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
515	            StringBuilder sb = new StringBuilder(digest.length * 2);
516	            for (byte b : digest) {
517	                sb.append(String.format("%02x", b));
518	            }
519	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
520	        } catch (NoSuchAlgorithmException e) {
521	            throw new IllegalStateException("SHA-256 not available", e);
522	        }
523	    }
524	
525	    /**
526	     * Counts the existing owners that share the owner-to-be's first and last name, compared
527	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
528	     * new owner is persisted, so it excludes the owner being created.
529	     *
530	     * @param firstName the first name of the owner being created
531	     * @param lastName the last name of the owner being created
532	     * @return the number of existing owners with the same first and last name
533	     */
534	    private int countNamesakes(String firstName, String lastName) {
535	        String normalizedFirstName = normalizeName(firstName);
536	        String normalizedLastName = normalizeName(lastName);
537	        return (int) this.clinicService.findAllOwners().stream()
538	            .filter(existing ->
539	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
540	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
541	            .count();
542	    }
543	
544	    /**
545	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
546	     * number of existing owners already carrying the same {@code householdId}. A household identifier
547	     * is only assigned to owners who knowingly share a household via {@code sharesHousehold}; a solo
548	     * owner has no household identifier ({@code null}) and is therefore always a household of one. The
549	     * count includes the owner being created (hence the {@code + 1}).
550	     *
551	     * @param householdId the stable household identifier of the owner being created, or {@code null}
552	     *     when the owner does not share a household
553	     * @return the number of household members after this create (always at least 1)
554	     */
555	    private int householdSize(String householdId) {
556	        if (householdId == null) {
557	            return 1;
558	        }
559	        return (int) this.clinicService.findAllOwners().stream()
560	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
561	            .count() + 1;
562	    }
563	
564	    /**
565	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
566	     * lower-casing.
567	     *
568	     * @param value the raw name, may be {@code null}
569	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
570	     */
571	    private static String normalizeName(String value) {
572	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
573	    }
574	
575	    /**
576	     * The fixed city-to-region table used to validate a postcode against its city
577	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). A city not in this table has no known region and
578	     * therefore accepts any 4-digit postcode.
579	     */
580	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
581	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
582	
583	    /**
584	     * The fixed region-to-postcode-range table: each region admits an inclusive 4-digit range
585	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
586	     */
587	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
588	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
589	
590	    /**
591	     * Validates an owner's optional postcode on create. A {@code null} or blank postcode is left
592	     * untouched (postcode is optional when absent). When present it must be exactly four digits and,
593	     * when the city maps to a known region, must fall within that region's inclusive range
594	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
595	     * postcode.
596	     *
597	     * @param city the city of the owner being created
598	     * @param postcode the raw postcode as supplied by the caller, may be {@code null}
599	     * @throws InvalidPostcodeException if a present postcode is not four digits or is out of range
600	     *     for the city's region
601	     */
602	    private static void validatePostcode(String city, String postcode) {
603	        if (postcode == null || postcode.isBlank()) {
604	            return;
605	        }
606	        if (!postcode.matches("\\d{4}")) {
607	            throw new InvalidPostcodeException("Postcode must be exactly 4 digits");
608	        }
609	        String region = CITY_REGION.get(city);
610	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
611	        if (range != null) {
612	            int value = Integer.parseInt(postcode);
613	            if (value < range[0] || value > range[1]) {
614	                throw new InvalidPostcodeException(
615	                    "Postcode is out of range for the city's region");
616	            }
617	        }
618	    }
619	
620	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
621	    @Override
622	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
623	        Owner owner = this.clinicService.findOwnerById(ownerId);
624	        if (owner == null) {
625	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
626	        }
627	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
628	    }
629	
630	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
631	    @Override
632	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
633	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
634	        validateRequiredFields(ownerFieldsDto);
635	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
636	        if (registrationDate == null) {
637	            registrationDate = LocalDate.now();
638	        } else if (registrationDate.isAfter(LocalDate.now())) {
639	            throw new FutureRegistrationDateException(
640	                "registrationDate must not be later than the server date");
641	        }
642	        registrationDate = toBusinessDay(registrationDate);
643	        ownerFieldsDto.setRegistrationDate(registrationDate);
644	        rejectDailyOwnerLimit(registrationDate);
645	        rejectCityAtCapacity(ownerFieldsDto.getCity());
646	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
647	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
648	        ownerFieldsDto.setTelephone(normalizedTelephone);
649	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
650	        ownerFieldsDto.setEmail(normalizedEmail);
651	        String ownerHouseholdId = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
652	            ? householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress())
653	            : null;
654	        rejectDuplicateIdentity(deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerHouseholdId));
655	        Integer possibleDuplicateOf = findPossibleDuplicateOf(
656	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode(), normalizedTelephone);
657	        HttpHeaders headers = new HttpHeaders();
658	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
659	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
660	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
661	        owner.setCustomerCode(customerCode(
662	            ownerFieldsDto.getPostcode(), normalizedTelephone, ownerFieldsDto.getLastName()));
663	        owner.setHouseholdId(ownerHouseholdId);
664	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
665	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
666	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
667	        this.clinicService.saveOwner(owner);
668	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
669	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
670	            ownerMapper.membershipLevel(owner));
671	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
672	        headers.setLocation(UriComponentsBuilder.newInstance()
673	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
674	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
675	    }
676	
677	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
678	    @Override
679	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
680	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
681	        if (currentOwner == null) {
682	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
683	        }
684	        currentOwner.setAddress(ownerFieldsDto.getAddress());
685	        currentOwner.setCity(ownerFieldsDto.getCity());
686	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
687	        currentOwner.setLastName(ownerFieldsDto.getLastName());
688	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
689	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
690	        this.clinicService.saveOwner(currentOwner);
691	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
692	    }
693	
694	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
695	    @Transactional
696	    @Override
697	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
698	        Owner owner = this.clinicService.findOwnerById(ownerId);
699	        if (owner == null) {
700	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
701	        }
702	        this.clinicService.deleteOwner(owner);
703	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
704	    }
705	
706	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
707	    @Override
708	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
709	        Owner owner = this.clinicService.findOwnerById(ownerId);
710	        if (owner == null) {
711	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
712	        }
713	        HttpHeaders headers = new HttpHeaders();
714	        Pet pet = petMapper.toPet(petFieldsDto);
715	        owner.setId(ownerId);
716	        pet.setOwner(owner);
717	        pet.getType().setName(null);
718	        this.clinicService.savePet(pet);
719	        PetDto petDto = petMapper.toPetDto(pet);
720	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
721	            .buildAndExpand(pet.getId()).toUri());
722	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
723	    }
724	
725	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
726	    @Override
727	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
728	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
729	        if (currentOwner != null) {
730	            Pet currentPet = this.clinicService.findPetById(petId);
731	            if (currentPet != null) {
732	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
733	                currentPet.setName(petFieldsDto.getName());
734	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
735	                this.clinicService.savePet(currentPet);
736	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
737	            }
738	        }
739	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
740	    }
