742	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
743	    @Override
744	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
745	        HttpHeaders headers = new HttpHeaders();
746	        Visit visit = visitMapper.toVisit(visitFieldsDto);
747	        Pet pet = new Pet();
748	        pet.setId(petId);
749	        visit.setPet(pet);
750	        this.clinicService.saveVisit(visit);
751	        VisitDto visitDto = visitMapper.toVisitDto(visit);
752	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
753	            .buildAndExpand(visit.getId()).toUri());
754	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
755	    }
