757	
758	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
759	    @Override
760	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
761	        Owner owner = this.clinicService.findOwnerById(ownerId);
762	        if (owner != null) {
763	            Pet pet = owner.getPet(petId);
764	            if (pet != null) {
765	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
766	            }
767	        }
768	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
769	    }
